function validate([keyboard, word]) {
  if (typeof keyboard !== 'string' || keyboard.length !== 26 || !/^[a-z]+$/.test(keyboard) || new Set(keyboard).size !== 26) return 'keyboard must hold each lowercase letter exactly once.';
  if (typeof word !== 'string' || word.length < 1 || word.length > 10000) return 'word has 1 to 10000 characters.';
  if (!/^[a-z]+$/.test(word)) return 'word uses lowercase English letters only.';
  return null;
}

