function calculateTime(keyboard, word) {
  const position = new Map();
  for (let i = 0; i < keyboard.length; i++) {
    position.set(keyboard[i], i);
  }
  let time = 0;
  let current = 0;
  for (const letter of word) {
    const index = position.get(letter);
    time += Math.abs(index - current);
    current = index;
  }
  return time;
}

brute:
function calculateTime(keyboard, word) {
  let total = 0;
  let at = 0;
  for (let i = 0; i < word.length; i++) {
    let to = 0;
    while (keyboard[to] !== word[i]) to++;
    total += to > at ? to - at : at - to;
    at = to;
  }
  return total;
}

