function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const letters = 'abcdefghijklmnopqrstuvwxyz'.split('');
  if (rand() < 0.7) {
    for (let i = 25; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [letters[i], letters[j]] = [letters[j], letters[i]]; }
  }
  const keyboard = letters.join('');
  const large = size === 'large';
  const length = large ? int(5000, 10000) : int(1, 12);
  // Use a random subset of letters so repeats and short hops appear.
  const pool = 'abcdefghijklmnopqrstuvwxyz'.slice(0, int(1, 26)).split('');
  let word = '';
  for (let i = 0; i < length; i++) word += rand() < 0.5 ? pool[Math.floor(rand() * pool.length)] : letters[Math.floor(rand() * 26)];
  return [keyboard, word];
}
